// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 프로필 수정 (18번)" (ffc16dac3577418ea10d8d34dd960a15).
// REQ-MYPAGE-002: 닉네임(중복 확인)·소개글·경력(연차·기술 스택) 수정 (#30)
// #190: docs/ui-guide.md 공통 값(uiStyles, ConfirmModal, FieldError, ListStatus)으로 바꿨다.
import { useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorCode, getErrorMessage, getFieldErrors } from "../api/client";
import { checkAvailable } from "../api/member";
import {
  getMyCategories,
  getMyInfo,
  updateMyCategories,
  updateProfile,
  type CategorySetting,
  type MyInfo,
  type ProfileUpdateRequest,
} from "../api/mypage";
import { getCategories, type Category } from "../api/tag";
import ConfirmModal from "../components/ConfirmModal";
import FieldError from "../components/FieldError";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import { formatCareer } from "../components/ProfileDetails";
import TagAutocomplete from "../components/tag/TagAutocomplete";
import { buttonClass, CARD, CHIP, chipClass, INPUT, NOTICE, PAGE_BACKGROUND } from "../components/uiStyles";
import { useAuth } from "../hooks/useAuth";
import { usePageTitle } from "../hooks/usePageTitle";
import "./ProfileEdit.css";

// 서버와 같은 입력값 규칙 (docs/api.md 입력값 규칙)
const NICKNAME_PATTERN = /^[가-힣A-Za-z0-9]{2,10}$/;
const NICKNAME_RULE = "2~10자, 한글·영문·숫자만 쓸 수 있어요 (공백·특수기호 불가).";
const BIO_MAX_LENGTH = 200;
const CAREER_YEARS_MAX = 50;
const TECH_STACK_MAX = 5;

const ICON = "material-symbols-outlined text-[18px] leading-none shrink-0";
const SMALL_ICON = "material-symbols-outlined text-[15px] leading-none";
const CARD_PADDING = "p-4 sm:p-6";

// 새 질문 알림 스위치: 꺼짐은 회색 바탕, 켜짐은 검정 바탕 (노랑은 강조에만 쓴다, ui-guide.md 1절)
const SWITCH_TRACK = [
  "w-12 h-6 rounded-full border-devin border-devin-ink bg-devin-tag transition-colors peer-checked:bg-devin-ink",
  "peer-focus-visible:outline peer-focus-visible:outline-[3px] peer-focus-visible:outline-devin-blue peer-focus-visible:outline-offset-2",
  "after:content-[''] after:absolute after:top-[4px] after:left-[4px] after:h-4 after:w-4 after:rounded-full",
  "after:bg-devin-paper after:border-devin after:border-devin-ink after:transition-all peer-checked:after:translate-x-6",
].join(" ");

type Field = "nickname" | "bio" | "careerYears" | "techStacks" | "categories";
type Errors = Partial<Record<Field | "form", string>>;

// 연차 선택지: 선택 안 함(null), 신입(0), 1~50년차
const CAREER_OPTIONS = Array.from({ length: CAREER_YEARS_MAX + 1 }, (_, years) => years);

// 관심 카테고리·알림(categoryIds, notificationEnabled)은 PUT /me/categories로 따로 저장한다 (REQ-MYPAGE-004).
interface FormValues extends CategorySetting {
  nickname: string;
  bio: string;
  careerYears: number | null;
  techStacks: string[];
}

// 중복 확인 결과. value가 지금 입력값과 다르면(확인 후 수정) 다시 확인해야 한다.
interface NicknameCheck {
  value: string;
  available: boolean;
}

function toFormValues(me: MyInfo, setting: CategorySetting): FormValues {
  return {
    nickname: me.nickname,
    bio: me.bio ?? "",
    careerYears: me.careerYears,
    techStacks: me.techStacks,
    categoryIds: setting.categoryIds,
    notificationEnabled: setting.notificationEnabled,
  };
}

function categoriesChanged(initial: FormValues, values: FormValues) {
  const sorted = (ids: number[]) => [...ids].sort((a, b) => a - b).join();
  return (
    sorted(initial.categoryIds) !== sorted(values.categoryIds) ||
    initial.notificationEnabled !== values.notificationEnabled
  );
}

// 처음 값과 달라진 필드만 보낸다 (docs/api.md "보낸 필드만 바꾼다").
function toRequest(initial: FormValues, values: FormValues): ProfileUpdateRequest {
  const request: ProfileUpdateRequest = {};
  if (values.nickname !== initial.nickname) request.nickname = values.nickname;
  if (values.bio !== initial.bio) request.bio = values.bio === "" ? null : values.bio;
  if (values.careerYears !== initial.careerYears) request.careerYears = values.careerYears;
  if (values.techStacks.join() !== initial.techStacks.join()) request.techStacks = values.techStacks;
  return request;
}

// 입력칸 아래 안내(info)·확인(ok) 문구. 오류는 공통 FieldError를 쓴다.
function Hint({ tone, children }: { tone: "info" | "ok"; children: ReactNode }) {
  return (
    <p className={`${INPUT.hint} flex items-center gap-1 ${tone === "ok" ? "font-bold text-devin-ink" : ""}`}>
      <span className={SMALL_ICON} aria-hidden="true">
        {tone === "ok" ? "check_circle" : "info"}
      </span>
      {children}
    </p>
  );
}

function ErrorNotice({ message }: { message: string }) {
  return (
    <p className={NOTICE.error} role="alert">
      <span className={ICON} aria-hidden="true">
        error
      </span>
      {message}
    </p>
  );
}

export default function ProfileEdit() {
  usePageTitle("프로필 수정");
  const navigate = useNavigate();
  const { user, initializing, refreshUser } = useAuth();
  const [initial, setInitial] = useState<FormValues | null>(null);
  const [values, setValues] = useState<FormValues | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [categories, setCategories] = useState<Category[]>([]);
  const [nicknameCheck, setNicknameCheck] = useState<NicknameCheck | null>(null);
  const [checking, setChecking] = useState(false);
  const [errors, setErrors] = useState<Errors>({});
  const [submitting, setSubmitting] = useState(false);
  const [completed, setCompleted] = useState(false);

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  // 저장 후 refreshUser로 user가 바뀌어도 폼을 다시 불러오지 않도록 memberId에만 반응한다.
  const memberId = user?.memberId;
  useEffect(() => {
    if (memberId === undefined) return;
    let cancelled = false;
    Promise.all([getMyInfo(), getMyCategories(), getCategories()])
      .then(([me, setting, categoryList]) => {
        if (cancelled) return;
        setInitial(toFormValues(me, setting));
        setValues(toFormValues(me, setting));
        setCategories(categoryList);
      })
      .catch((error) => {
        if (!cancelled) setLoadError(getErrorMessage(error, "프로필을 불러오지 못했어요. 잠시 후 다시 시도해 주세요."));
      });
    return () => {
      cancelled = true;
    };
  }, [memberId]);

  const update = <K extends keyof FormValues>(field: K, value: FormValues[K]) => {
    setValues((prev) => (prev ? { ...prev, [field]: value } : prev));
    setErrors((prev) => ({ ...prev, [field]: undefined, form: undefined }));
  };

  const nicknameChanged = Boolean(values && initial && values.nickname !== initial.nickname);
  const nicknameChecked = nicknameCheck !== null && values !== null && nicknameCheck.value === values.nickname;

  async function handleCheckNickname() {
    if (!values || checking) return;
    if (!nicknameChanged) {
      setErrors((prev) => ({ ...prev, nickname: undefined }));
      setNicknameCheck({ value: values.nickname, available: true });
      return;
    }
    if (!NICKNAME_PATTERN.test(values.nickname)) {
      setErrors((prev) => ({ ...prev, nickname: NICKNAME_RULE }));
      return;
    }
    setChecking(true);
    try {
      const available = await checkAvailable("nickname", values.nickname);
      setNicknameCheck({ value: values.nickname, available });
      setErrors((prev) => ({ ...prev, nickname: available ? undefined : "이미 사용 중인 닉네임이에요." }));
    } catch (error) {
      setErrors((prev) => ({ ...prev, nickname: getErrorMessage(error) }));
    } finally {
      setChecking(false);
    }
  }

  // 기술 스택은 태그 목록(GET /api/tags)에서 자동완성으로 고른다 (REQ-MYPAGE-002 "선택형(태그)").
  function addTechStack(name: string) {
    if (!values || values.techStacks.includes(name)) return;
    if (values.techStacks.length >= TECH_STACK_MAX) {
      setErrors((prev) => ({ ...prev, techStacks: `기술 스택은 최대 ${TECH_STACK_MAX}개까지 고를 수 있어요.` }));
      return;
    }
    update("techStacks", [...values.techStacks, name]);
  }

  function toggleCategory(categoryId: number) {
    if (!values) return;
    const selected = values.categoryIds.includes(categoryId);
    update(
      "categoryIds",
      selected ? values.categoryIds.filter((id) => id !== categoryId) : [...values.categoryIds, categoryId],
    );
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!values || !initial || submitting) return;

    const found: Errors = {};
    if (nicknameChanged) {
      if (!NICKNAME_PATTERN.test(values.nickname)) {
        found.nickname = NICKNAME_RULE;
      } else if (!nicknameChecked) {
        found.nickname = "닉네임 중복 확인을 해 주세요.";
      } else if (!nicknameCheck?.available) {
        found.nickname = "이미 사용 중인 닉네임이에요.";
      }
    }
    if (values.bio.length > BIO_MAX_LENGTH) {
      found.bio = `소개글은 ${BIO_MAX_LENGTH}자 이하로 입력해 주세요.`;
    }
    const request = toRequest(initial, values);
    const profileChanged = Object.keys(request).length > 0;
    const categoryChanged = categoriesChanged(initial, values);
    if (Object.keys(found).length === 0 && !profileChanged && !categoryChanged) {
      found.form = "바꾼 내용이 없어요.";
    }
    setErrors(found);
    if (Object.keys(found).length > 0) return;

    setSubmitting(true);
    try {
      if (profileChanged) {
        await updateProfile(request);
        // 헤더 등에 보이는 로그인 닉네임도 바꾼다.
        if (request.nickname !== undefined) await refreshUser().catch(() => {});
        // 카테고리 저장이 실패해도 프로필 수정분은 저장된 상태로 둔다.
        setInitial((prev) =>
          prev ? { ...values, categoryIds: prev.categoryIds, notificationEnabled: prev.notificationEnabled } : prev,
        );
      }
      if (categoryChanged) {
        await updateMyCategories({ categoryIds: values.categoryIds, notificationEnabled: values.notificationEnabled });
      }
      setInitial(values);
      setCompleted(true);
    } catch (error) {
      const code = getErrorCode(error);
      if (code === "CATEGORY_NOT_FOUND") {
        setErrors({ categories: getErrorMessage(error) });
      } else if (code === "DUPLICATE_NICKNAME") {
        setNicknameCheck({ value: values.nickname, available: false });
        setErrors({ nickname: "이미 사용 중인 닉네임이에요." });
      } else if (code === "INVALID_INPUT") {
        const next: Errors = {};
        getFieldErrors(error).forEach(({ field, reason }) => {
          next[
            (["nickname", "bio", "careerYears", "techStacks"] as string[]).includes(field) ? (field as Field) : "form"
          ] = reason;
        });
        setErrors(Object.keys(next).length > 0 ? next : { form: getErrorMessage(error) });
      } else {
        setErrors({ form: getErrorMessage(error) });
      }
    } finally {
      setSubmitting(false);
    }
  }

  let nicknameHint: ReactNode = null;
  if (errors.nickname) nicknameHint = <FieldError message={errors.nickname} />;
  else if (nicknameChanged && nicknameChecked && nicknameCheck?.available)
    nicknameHint = <Hint tone="ok">사용할 수 있는 닉네임이에요.</Hint>;
  else if (nicknameChanged) nicknameHint = <Hint tone="info">닉네임을 바꾸면 중복 확인이 필요해요.</Hint>;

  return (
    <div id="page-profile-edit">
      <div className={`${PAGE_BACKGROUND} min-h-screen text-devin-ink antialiased pb-8`}>
        <Header />
        <main className="max-w-3xl mx-auto space-y-6 px-4 sm:px-6 py-6" data-purpose="profile-edit-container">
          <header className="flex flex-wrap items-center justify-between gap-3" data-purpose="page-header">
            <h1 className="text-2xl font-black">프로필 수정</h1>
            <Link className={buttonClass("secondary", "sm")} data-purpose="return-mypage-btn" to="/mypage">
              <span className={ICON} aria-hidden="true">
                arrow_back
              </span>
              마이페이지
            </Link>
          </header>

          {loadError && <ErrorNotice message={loadError} />}
          {!values && !loadError && <ListStatus kind="loading">프로필을 불러오는 중이에요.</ListStatus>}

          {values && (
            <form className="space-y-6" id="profile-edit-form" noValidate onSubmit={handleSubmit}>
              {/* 기본 정보 */}
              <section className={`${CARD} ${CARD_PADDING} space-y-5`} data-purpose="basic-info-section">
                <div>
                  <label className={INPUT.label} htmlFor="nickname">
                    닉네임
                  </label>
                  <div className="flex flex-col sm:flex-row gap-2">
                    <input
                      aria-invalid={Boolean(errors.nickname)}
                      className={`${INPUT.base} flex-1 ${errors.nickname ? INPUT.error : ""}`}
                      id="nickname"
                      maxLength={10}
                      name="nickname"
                      onChange={(e) => update("nickname", e.target.value)}
                      placeholder="닉네임을 입력하세요"
                      type="text"
                      value={values.nickname}
                    />
                    <button
                      className={`${buttonClass("secondary")} shrink-0`}
                      data-purpose="check-duplicate-btn"
                      disabled={checking}
                      onClick={handleCheckNickname}
                      type="button"
                    >
                      {checking ? "확인 중..." : "중복 확인"}
                    </button>
                  </div>
                  {nicknameHint}
                </div>

                <div>
                  <label className={INPUT.label} htmlFor="bio">
                    소개글
                  </label>
                  <textarea
                    aria-describedby="char-counter"
                    aria-invalid={Boolean(errors.bio)}
                    className={`${INPUT.box} block resize-none ${errors.bio ? INPUT.error : ""}`}
                    id="bio"
                    maxLength={BIO_MAX_LENGTH}
                    name="bio"
                    onChange={(e) => update("bio", e.target.value)}
                    placeholder="자신을 자유롭게 소개해 주세요."
                    rows={4}
                    value={values.bio}
                  />
                  <div className="flex items-start justify-between gap-3">
                    {errors.bio ? (
                      <FieldError message={errors.bio} />
                    ) : (
                      <Hint tone="info">비워 두고 저장하면 소개글이 지워져요.</Hint>
                    )}
                    {/* 글자 수 표시 (REQ-MYPAGE-002) */}
                    <span
                      className={`mt-1.5 shrink-0 text-xs tabular-nums ${
                        values.bio.length >= BIO_MAX_LENGTH ? "font-bold text-devin-red" : "text-devin-gray"
                      }`}
                      id="char-counter"
                    >
                      {values.bio.length} / {BIO_MAX_LENGTH}
                    </span>
                  </div>
                </div>
              </section>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6" data-purpose="details-grid">
                {/* 경력: 연차(선택 안 함·신입·1~50년차) + 기술 스택 */}
                <section
                  className={`${CARD} ${CARD_PADDING} flex flex-col justify-between gap-5`}
                  data-purpose="career-section"
                >
                  <div className="space-y-5">
                    <h2 className="pb-3 border-b-2 border-devin-line text-lg font-extrabold">경력</h2>

                    <div>
                      <label className={INPUT.label} htmlFor="experience-years">
                        연차
                      </label>
                      <div className="relative w-40">
                        <select
                          className={`${INPUT.base} appearance-none pr-9 cursor-pointer`}
                          id="experience-years"
                          name="experience_years"
                          onChange={(e) => update("careerYears", e.target.value === "" ? null : Number(e.target.value))}
                          value={values.careerYears ?? ""}
                        >
                          <option value="">선택 안 함</option>
                          {CAREER_OPTIONS.map((years) => (
                            <option key={years} value={years}>
                              {formatCareer(years)}
                            </option>
                          ))}
                        </select>
                        <span
                          className={`${ICON} pointer-events-none absolute inset-y-0 right-2.5 flex items-center`}
                          aria-hidden="true"
                        >
                          expand_more
                        </span>
                      </div>
                      <FieldError message={errors.careerYears} />
                    </div>

                    <div>
                      <span className={INPUT.label}>
                        기술 스택{" "}
                        <span className="font-semibold text-devin-gray tabular-nums">
                          ({values.techStacks.length} / {TECH_STACK_MAX})
                        </span>
                      </span>
                      <div
                        className="flex flex-wrap gap-1.5 min-h-[22px] mb-2"
                        data-purpose="tech-badges"
                        id="tech-stack-badges"
                      >
                        {values.techStacks.length === 0 && (
                          <span className="text-xs text-devin-gray-light">등록한 기술 스택이 없어요.</span>
                        )}
                        {values.techStacks.map((name) => (
                          <span className={CHIP.removable} key={name}>
                            {name}
                            <button
                              aria-label={`${name} 지우기`}
                              className={CHIP.remove}
                              onClick={() =>
                                update(
                                  "techStacks",
                                  values.techStacks.filter((t) => t !== name),
                                )
                              }
                              type="button"
                            >
                              <span className={SMALL_ICON} aria-hidden="true">
                                close
                              </span>
                            </button>
                          </span>
                        ))}
                      </div>
                      {/* 태그 목록(GET /api/tags)에서 자동완성으로 고른다. ↑↓로 고르고 Enter로 추가 */}
                      <div data-purpose="tech-stack-autocomplete">
                        <TagAutocomplete
                          disabled={values.techStacks.length >= TECH_STACK_MAX}
                          onSelect={addTechStack}
                          placeholder="기술 스택 검색 (예: java)"
                          selected={values.techStacks}
                        />
                      </div>
                      <FieldError message={errors.techStacks} />
                    </div>
                  </div>

                  <p className="pt-3 border-t border-devin-line text-xs text-devin-gray">
                    등록한 경력은 질문·답변의 닉네임 옆에 함께 보여요.
                  </p>
                </section>

                {/* 관심 카테고리·새 질문 알림 (REQ-MYPAGE-004): GET /api/categories 목록에서 여러 개 선택 */}
                <section
                  className={`${CARD} ${CARD_PADDING} flex flex-col justify-between gap-5`}
                  data-purpose="interests-section"
                >
                  <div className="space-y-4">
                    <div className="pb-3 border-b-2 border-devin-line">
                      <h2 className="text-lg font-extrabold">관심 카테고리</h2>
                      <p className="mt-0.5 text-xs text-devin-gray">
                        관심 카테고리에 새 질문이 올라오면 알림을 받아요.
                      </p>
                    </div>
                    <div className="flex flex-wrap gap-2" data-purpose="interest-tag-badges" id="interest-badges">
                      {categories.map((category) => {
                        const selected = values.categoryIds.includes(category.categoryId);
                        return (
                          <button
                            aria-pressed={selected}
                            className={chipClass(selected)}
                            data-category-id={category.categoryId}
                            key={category.categoryId}
                            onClick={() => toggleCategory(category.categoryId)}
                            type="button"
                          >
                            {selected && (
                              <span className={SMALL_ICON} aria-hidden="true">
                                check
                              </span>
                            )}
                            {category.name}
                          </button>
                        );
                      })}
                    </div>
                    <FieldError message={errors.categories} />
                  </div>
                  <div
                    className="pt-3 border-t border-devin-line flex items-center justify-between gap-3"
                    data-purpose="notification-toggle-wrapper"
                  >
                    <label className="text-sm font-bold" htmlFor="notification-toggle">
                      새 질문 알림
                    </label>
                    <label className="relative inline-flex items-center cursor-pointer">
                      <input
                        checked={values.notificationEnabled}
                        className="sr-only peer"
                        id="notification-toggle"
                        onChange={(e) => update("notificationEnabled", e.target.checked)}
                        role="switch"
                        type="checkbox"
                      />
                      <span aria-hidden="true" className={SWITCH_TRACK} />
                    </label>
                  </div>
                </section>
              </div>

              {errors.form && <ErrorNotice message={errors.form} />}

              <div className="flex items-center justify-end gap-2" data-purpose="form-actions">
                <button
                  className={buttonClass("secondary")}
                  data-purpose="cancel-btn"
                  onClick={() => navigate("/mypage")}
                  type="button"
                >
                  취소
                </button>
                <button className={buttonClass("primary")} data-purpose="save-btn" disabled={submitting} type="submit">
                  {submitting ? "저장 중..." : "저장"}
                </button>
              </div>
            </form>
          )}
        </main>
      </div>
      {completed && (
        <ConfirmModal
          confirmLabel="마이페이지로 이동"
          message="마이페이지에서 바뀐 프로필을 확인해 보세요."
          onCancel={() => setCompleted(false)}
          onConfirm={() => navigate("/mypage")}
          title="프로필을 바꿨어요"
        />
      )}
    </div>
  );
}
